import Foundation

/// Values read from the app bundle (Info.plist generated by the Xcode project).
enum AppInfo {
    static var version: String {
        Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "—"
    }

    static var build: String {
        Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String ?? "—"
    }

    static var versionDescription: String { "\(version) (\(build))" }

    static var bundleIdentifier: String { Bundle.main.bundleIdentifier ?? "—" }

    /// Shown on Home and in Settings → About. Update with each milestone.
    static let developmentStage = "Development build — M2 Stage 1 (simulated trading)"
}
